sources_fetch(){ local manifest="$LFSFORGE_ROOT/lfs-versions/${CFG_LFS_VERSION:-unspecified}.manifest"; mkdir -p "$CFG_SOURCES_DIR"; [[ -f "$manifest" ]] || { warn "No hay manifest para LFS_VERSION=${CFG_LFS_VERSION:-unspecified}. Usa un manifest oficial verificado."; return 1; }; local name url sha dest; while IFS=$'\t' read -r name url sha || [[ -n "$name" ]]; do [[ -z "$name" || "$name" == \#* ]] && continue; dest="$CFG_SOURCES_DIR/${url##*/}"; if [[ -f "$dest" ]]; then info "Existe: $dest"; else info "Downloading $name..."; curl --fail --location --retry 3 --output "$dest" "$url" || { error "Descarga fallida: $url"; return 1; }; fi; [[ "$sha" == '-' ]] && { warn "Sin SHA256 para $name; no se considera verificado"; continue; }; echo "$sha  $dest" | sha256sum -c - || { error "SHA256 inválido para $name"; return 1; }; done < "$manifest"; }
